Bytes ScriptSession::encodeTreeActions(const jass::StableHandleMap& encodeHandle) const {
    constexpr size_t budget=64u*1024u*1024u;if(!runtime_.snapshotSafe() || failed_ || !world_ || !setupApplied_ || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty() || ((!units_.empty() || !eatenTrees_.empty()) && !encodeHandle) || units_.size()>65536 || eatenTrees_.size()>65536)throw std::runtime_error("Tree action snapshot requires a quiescent local session");for(auto id:eatTreeActors_)if(!units_.contains(id))throw std::runtime_error("Invalid eat tree actor");for(auto id:warClubActors_)if(!units_.contains(id))throw std::runtime_error("Invalid war club actor");std::map<std::pair<NativeKind,std::uint32_t>,std::uint32_t> forward,reverse;auto ref=[&](std::uint32_t id,NativeKind kind){if(!id)return 0u;if(id<handleBase || id-handleBase>=objects_.size() || objects_[id-handleBase].kind!=kind)throw std::runtime_error("Invalid tree action reference");auto name=kind==NativeKind::Unit?"unit":kind==NativeKind::Effect?"effect":"destructable";auto key=encodeHandle(name,id);auto [a,inserted]=forward.emplace(std::pair{kind,id},key);auto [b,unique]=reverse.emplace(std::pair{kind,key},id);if(!key || (!inserted && a->second!=key) || (!unique && b->second!=id))throw std::runtime_error("Invalid tree action mapping");return key;};std::map<std::uint32_t,const UnitState*> ordered;for(auto& [id,u]:units_)ordered.emplace(ref(id,NativeKind::Unit),u.get());SnapshotWriter out(budget-64);out.u32(tag("STRS"));out.u32(1);out.text(world_->resources().mapDigest(),64);out.u64(std::bit_cast<std::uint64_t>(simulationTime_));out.size(ordered.size());auto time=[&](double value){if(!std::isfinite(value))throw std::runtime_error("Invalid tree action time");out.u64(std::bit_cast<std::uint64_t>(value));};for(auto [key,u]:ordered){out.u32(key);out.u32(eatTreeActors_.contains(u->handle));out.u32(warClubActors_.contains(u->handle));out.u32(u->eatTree.has_value());if(u->eatTree){auto& e=*u->eatTree;if(!e.tree)throw std::runtime_error("Missing eaten tree");writeSpellSnapshot(out,e.spell);out.u32(ref(e.tree,NativeKind::Destructable));out.u64(e.ticket);time(e.elapsed);out.u32(e.ripped);}out.u32(u->grabTree.has_value());if(u->grabTree){auto& g=*u->grabTree;if(!g.tree)throw std::runtime_error("Missing grabbed tree");writeSpellSnapshot(out,g.spell);out.u32(ref(g.tree,NativeKind::Destructable));out.u64(g.ticket);time(g.elapsed);out.u32(g.consumed);}out.u32(u->warClub.has_value());if(u->warClub){auto& c=*u->warClub;writeSpellSnapshot(out,c.spell);out.u32(c.attacks);time(c.elapsed);out.u32(c.dropping);out.u32(ref(c.visual,NativeKind::Effect));}}
    std::map<std::uint32_t,std::pair<std::uint32_t,std::uint64_t>> claims;for(auto [tree,claim]:eatenTrees_){auto key=ref(tree,NativeKind::Destructable),actor=ref(claim.first,NativeKind::Unit);if(!key || !actor || !claims.emplace(key,std::pair{actor,claim.second}).second)throw std::runtime_error("Invalid tree claim");}out.size(claims.size());for(auto [tree,claim]:claims){out.u32(tree);out.u32(claim.first);out.u64(claim.second);}return sealSnapshot(out.finish(),budget);
}
void ScriptSession::restoreTreeActions(std::span<const std::uint8_t> bytes,const jass::StableHandleMap& decodeHandle) {
    constexpr size_t budget=64u*1024u*1024u;if(!runtime_.ready() || failed_ || !world_ || !setupApplied_ || mainAttempted_ || !unitRecoveryIncomplete_ || !unitCoreFinished_ || treeActionsRestored_ || runtime_.threadCount() || !runtime_.inspectExecutions().empty() || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty() || liveObjects(NativeKind::Event))throw std::runtime_error("Tree actions restore requires rebuilt world before events");Binary in(openSnapshot(bytes,budget));in.expect(tag("STRS"));if(in.u32()!=1 || snapshotText(in,64)!=world_->resources().mapDigest() || snapshotU64(in)!=std::bit_cast<std::uint64_t>(simulationTime_))throw std::runtime_error("Tree actions snapshot map or clock differs");auto count=in.count(24,65536);if(count!=units_.size() || (count && !decodeHandle))throw std::runtime_error("Tree action unit count or mapping differs");std::map<std::pair<NativeKind,std::uint32_t>,std::uint32_t> reverse;auto ref=[&](std::uint32_t key,NativeKind kind){if(!key)return 0u;if(!decodeHandle)throw std::runtime_error("Tree action mapping missing");auto name=kind==NativeKind::Unit?"unit":kind==NativeKind::Effect?"effect":"destructable";auto id=decodeHandle(name,key);auto& identities=kind==NativeKind::Unit?unitIdentityHandles_:kind==NativeKind::Effect?effectIdentityHandles_:destructableIdentityHandles_;auto [it,unique]=reverse.emplace(std::pair{kind,id},key);if(!id || id<handleBase || id-handleBase>=objects_.size() || objects_[id-handleBase].kind!=kind || !identities.contains(key) || identities.at(key)!=id || (!unique && it->second!=key))throw std::runtime_error("Invalid tree action reference mapping");return id;};auto flag=[&](){auto value=in.u32();if(value>1)throw std::runtime_error("Invalid tree action flag");return value!=0;};auto time=[&](){auto value=std::bit_cast<double>(snapshotU64(in));if(!std::isfinite(value))throw std::runtime_error("Invalid tree action time");return value;};struct Saved{std::uint32_t id;bool eatActor,clubActor;std::optional<EatTreeState> eat;std::optional<GrabTreeState> grab;std::optional<WarClubState> club;};std::vector<Saved> saved;saved.reserve(count);std::set<std::uint32_t> seen;for(unsigned i=0;i<count;++i){auto id=ref(in.u32(),NativeKind::Unit);if(!id || !seen.insert(id).second || !alive(id,NativeKind::Unit) || !units_.contains(id))throw std::runtime_error("Invalid tree action unit");Saved v{id,flag(),flag(),{},{},{}};if(flag()){EatTreeState e;e.spell=readSpellSnapshot(in);e.tree=ref(in.u32(),NativeKind::Destructable);e.ticket=snapshotU64(in);e.elapsed=time();e.ripped=flag();if(!e.tree)throw std::runtime_error("Missing eaten tree");v.eat=std::move(e);}if(flag()){GrabTreeState g;g.spell=readSpellSnapshot(in);g.tree=ref(in.u32(),NativeKind::Destructable);g.ticket=snapshotU64(in);g.elapsed=time();g.consumed=flag();if(!g.tree)throw std::runtime_error("Missing grabbed tree");v.grab=std::move(g);}if(flag()){WarClubState c;c.spell=readSpellSnapshot(in);c.attacks=in.u32();c.elapsed=time();c.dropping=flag();c.visual=ref(in.u32(),NativeKind::Effect);v.club=std::move(c);}saved.push_back(std::move(v));}std::map<std::uint32_t,std::pair<std::uint32_t,std::uint64_t>> claims;count=in.count(16,65536);for(unsigned i=0;i<count;++i){auto tree=ref(in.u32(),NativeKind::Destructable),actor=ref(in.u32(),NativeKind::Unit);auto ticket=snapshotU64(in);if(!tree || !actor || !claims.emplace(tree,std::pair{actor,ticket}).second)throw std::runtime_error("Invalid tree claim");}in.finish();eatTreeActors_.clear();warClubActors_.clear();for(auto& v:saved){auto& u=*units_.at(v.id);u.eatTree=std::move(v.eat);u.grabTree=std::move(v.grab);u.warClub=std::move(v.club);if(v.eatActor)eatTreeActors_.insert(v.id);if(v.clubActor)warClubActors_.insert(v.id);}eatenTrees_.swap(claims);treeActionsRestored_=true;
}
bool ScriptSession::eatTreeTarget(const UnitState& u,std::uint32_t id,bool visibility){
    if(!alive(id,NativeKind::Destructable))return false;auto tree=destructables_.at(id);if(!tree->tree || !tree->visible || tree->removed || tree->life<=0 || tree->invulnerable)return false;auto claim=eatenTrees_.find(id);return (claim==eatenTrees_.end() || claim->second.first==u.handle) && (!visibility || fog(u.owner).state(tree->position)==4);
}
void ScriptSession::startEatTree(std::uint32_t id,const CastOrder& cast){
    if(!alive(id,NativeKind::Unit))return;auto u=units_.at(id);if(!eatTreeTarget(*u,cast.target,false)){cancelCast(*u);return;}eatenTrees_[cast.target]={id,cast.ticket};u->eatTree=EatTreeState{cast.spell,cast.target,cast.ticket};u->cast->phase=CastOrder::Phase::Channel;u->animation="Spell Eat Tree";u->animationTime=0;++u->animationGeneration;u->animationIndex.reset();u->animationQueue.clear();u->route.clear();u->waypoint=0;eatTreeActors_.insert(id);
}
void ScriptSession::cancelEatTree(UnitState& u,std::uint64_t ticket){if(!u.eatTree || u.eatTree->ticket!=ticket)return;auto state=*u.eatTree;u.eatTree.reset();eatTreeActors_.erase(u.handle);auto found=eatenTrees_.find(state.tree);if(found!=eatenTrees_.end() && found->second==std::pair{u.handle,ticket})eatenTrees_.erase(found);}
void ScriptSession::eatTreesTick(double delta){
    std::vector<std::uint32_t> actors(eatTreeActors_.begin(),eatTreeActors_.end());for(auto id:actors){if(!alive(id,NativeKind::Unit)){eatTreeActors_.erase(id);continue;}auto u=units_.at(id);if(!u->eatTree){eatTreeActors_.erase(id);continue;}auto state=*u->eatTree;auto active=[&]{return alive(id,NativeKind::Unit) && !u->removing && number(u->life)>0 && u->eatTree && u->eatTree->ticket==state.ticket && u->cast && u->cast->ticket==state.ticket;};if(!active()){cancelEatTree(*u,state.ticket);continue;}if(u->paused)continue;if(u->stunned() || u->morphed() || u->hidden()){cancelCast(*u);continue;}u->eatTree->elapsed+=delta;
        if(!u->eatTree->ripped && u->eatTree->elapsed>=state.spell.castDelay){if(!eatTreeTarget(*u,state.tree,false)){cancelCast(*u);continue;}u->eatTree->ripped=true;destructableLife(state.tree,0);if(!active())continue;auto visuals=spellVisual(state.spell,"Specialart",id,{u->x,u->y},false);u->cast->visuals.insert(u->cast->visuals.end(),visuals.begin(),visuals.end());}
        if(!active() || u->eatTree->elapsed<state.spell.channelTime)continue;cancelEatTree(*u,state.ticket);applyBuff(id,id,state.spell,BuffKind::EatTree,true);if(!alive(id,NativeKind::Unit))continue;auto found=u->buffs.find(state.spell.buff);if(found!=u->buffs.end() && found->second.kind==BuffKind::EatTree){found->second.positive=true;found->second.healRate=state.spell.loss/state.spell.duration;}finishCast(id,state.ticket);
    }
}
